#include <iostream>
using namespace std;

// recursion adds each number down to the base case 0
long long sumTo(int n) {
    if (n == 0) {
        return 0;
    }
    return n + sumTo(n - 1);
}

int main() {
    int n;
    cin >> n;
    cout << "Sum 1..N is " << sumTo(n) << endl;
    return 0;
}

#include <iostream>
using namespace std;

// recursion multiplies down to the base case 0! = 1
long long factorial(int n) {
    if (n == 0) {
        return 1;
    }
    return n * factorial(n - 1);
}

int main() {
    int n;
    cin >> n;
    cout << "Factorial of " << n << " is " << factorial(n) << endl;
    return 0;
}

#include <iostream>
using namespace std;

// recursion prints the current number then dives to the next smaller one
void printDescending(int n) {
    if (n == 1) {
        cout << 1 << endl;
        return;
    }
    cout << n << " ";
    printDescending(n - 1);
}

int main() {
    int n;
    cin >> n;
    printDescending(n);
    return 0;
}

#include <iostream>
using namespace std;

// recursion counts down; the base case fires the rocket
void countdown(int n) {
    if (n == 0) {
        cout << "Liftoff!" << endl;
        return;
    }
    cout << n << endl;
    countdown(n - 1);
}

int main() {
    int n;
    cin >> n;
    countdown(n);
    return 0;
}

#include <iostream>
using namespace std;

// recursion multiplies the base until the exponent reaches 0
long long power(long long base, int exponent) {
    if (exponent == 0) {
        return 1;
    }
    return base * power(base, exponent - 1);
}

int main() {
    long long base;
    int exponent;
    cin >> base >> exponent;
    cout << "Power result: " << power(base, exponent) << endl;
    return 0;
}

#include <iostream>
using namespace std;

// recursion removes one digit per call until a single digit remains
int countDigits(long long n) {
    if (n < 10) {
        return 1;
    }
    return 1 + countDigits(n / 10);
}

int main() {
    long long n;
    cin >> n;
    cout << "Digit count: " << countDigits(n) << endl;
    return 0;
}

#include <iostream>
using namespace std;

// recursion reads one size per call and accumulates through a reference
void readSizes(long long &total, int remaining) {
    if (remaining == 0) {
        return;
    }
    long long size;
    cin >> size;
    total += size;
    readSizes(total, remaining - 1);
}

int main() {
    int n;
    cin >> n;
    long long total = 0;
    readSizes(total, n);
    cout << "Files: " << n << endl;
    cout << "Total size: " << total << " MB" << endl;
    return 0;
}

