// recursion dives to the top of the chain first, approvals print on the way back
void approve(int level) {
    if (level == 0) {
        return;
    }
    approve(level - 1);
    cout << "Level " << level << " approved" << endl;
}

int main() {
    int n;
    cin >> n;
    cout << "Approval chain started" << endl;
    approve(n);
